import type { Source } from "./Core";
/**
 * Creates a callbag source that, on subscribe, calls a source
 * factory to make a source for each new subscriber.
 *
 * Marble diagram:
 *   {defer(() => fromIter([a, b, c]))}
 *   "a b c |"
 *
 * @param sourceFactory The source factory function to invoke
 *   for each sink that subscribes to the output source.
 *
 * @internal
 */
export declare const defer: <T, E>(sourceFactory: () => Source<T, E>) => Source<T, E>;
